const icons = {
 arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>', up:'<path d="m6 18 12-12M6 6h12v12"/>',
 chevron:'<path d="m9 5 7 7-7 7"/>', down:'<path d="m6 9 6 6 6-6"/>', back:'<path d="M19 12H5m5-5-5 5 5 5"/>',
 check:'<path d="m5 12 4 4L19 6"/>', code:'<path d="m8 6-6 6 6 6m8-12 6 6-6 6M14 3l-4 18"/>',
 chat:'<path d="M5 4h14a2 2 0 0 1 2 2v10a2 2 0 0 1-2 2H9l-5 3v-3H3V6a2 2 0 0 1 2-2Z"/><path d="M7 9h10M7 13h6"/>',
 screen:'<rect x="2" y="3" width="20" height="14" rx="2"/><path d="M8 21h8m-4-4v4"/><circle cx="12" cy="10" r="3"/>',
 lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3m-4 4v3"/>',
 shield:'<path d="m12 2 8 3v6c0 5-8 11-8 11S4 16 4 11V5Z"/><path d="m8 11 3 3 5-5"/>',
 mail:'<rect x="2" y="4" width="20" height="16" rx="2"/><path d="m3 6 9 7 9-7"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
 sparkle:'<path d="m12 2 2.4 7.6L22 12l-7.6 2.4L12 22l-2.4-7.6L2 12l7.6-2.4Z"/>'
};
function icon(name,cls=''){return `<svg class="icon ${cls}" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.arrow}</svg>`;}
const mark='<svg class="brand-mark" viewBox="0 0 32 32" aria-hidden="true"><rect x="3" y="3" width="18" height="18" rx="2"/><rect class="fill" x="11" y="11" width="18" height="18" rx="2"/></svg>';
const logo={
 boa:'<span class="bank-logo boa"><svg viewBox="0 0 44 34" width="34" height="28" aria-hidden="true"><path fill="#d22735" d="m2 8 15-7 11 6-15 7zm8 10 15-7 11 6-15 7zm8 10 15-7 10 6-15 7z"/><path fill="#174880" d="m1 13 5-2 11 6-5 2zm0 7 9-4 11 6-9 4zm0 7 13-6 11 6-13 6z"/></svg><span>Bank of<br>America</span></span>',
 chase:'<span class="bank-logo chase">CHASE<svg width="25" height="25" viewBox="0 0 32 32" aria-hidden="true"><path fill="#147ac0" d="M10 1h12l9 9H10zm21 9v12l-9 9V10zM22 31H10l-9-9h21zM1 22V10l9-9v21z"/></svg></span>',
 amex:'<span class="bank-logo amex">AMERICAN<br>EXPRESS</span>',
 citi:'<span class="bank-logo citi">citi</span>',
 wells:'<span class="bank-logo wells">WELLS<br>FARGO</span>',
 capital:'<span class="bank-logo capital">Capital<b>One</b></span>'
};
const plans=[
 {id:'boa',name:'Bank of America',value:'6.00% APY',short:'Savings boost',detail:'Illustrative savings rate · 3 months',type:'Savings',description:'A sample savings offer to illustrate how participating experts could select a banking benefit. This rate and duration are fictional.'},
 {id:'chase',name:'Chase',value:'$300',short:'Welcome bonus',detail:'Illustrative new-account bonus',type:'Checking',description:'A sample welcome bonus to illustrate a checking-account benefit. No account opening or actual bonus is available through this prototype.'},
 {id:'amex',name:'American Express',value:'$200',short:'Rewards credit',detail:'Illustrative rewards benefit',type:'Rewards',description:'A sample rewards credit for the concept experience. It is not a real American Express promotion or credit offer.'},
 {id:'citi',name:'Citi',value:'$250',short:'Welcome bonus',detail:'Illustrative new-account bonus',type:'Checking',description:'A sample checking offer for exploring the registration flow. The amount is illustrative and no bank partnership is confirmed.'},
 {id:'wells',name:'Wells Fargo',value:'$150',short:'Account credit',detail:'Illustrative account benefit',type:'Banking',description:'A sample account credit included to demonstrate plan selection. This is not an available bank promotion.'},
 {id:'capital',name:'Capital One',value:'$200',short:'Savings bonus',detail:'Illustrative savings benefit',type:'Savings',description:'A sample savings bonus for the concept preview. No financial account is created and no reward is issued.'}
];
const state={first:'',last:'',email:'',plan:'',consent:false,showAll:false,submitted:false};
const app=document.querySelector('#app');
const dialog=document.querySelector('#info-dialog');
function escapeHtml(v){return String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function footer(){return `<footer class="site-footer"><div class="wrap"><div class="footer-top"><a href="#/" class="brand">${mark}HyperSquare</a><p>Experience worth sharing. Benefits worth exploring.</p><div class="footer-links"><button type="button" data-info="privacy">Privacy</button><button type="button" data-info="terms">Program details</button></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} HyperSquare</span><span><i class="preview-dot"></i>Concept preview · Sample offers, no bank affiliation</span></div></div></footer>`;}
function landing(){return `<section class="hero"><div class="wrap"><div class="hero-main animate-in"><div><div class="program-label">THE COBOL EXPERT PROGRAM</div><h1>Unlock offers.<em>You’ve earned it.</em></h1><p class="hero-copy">Your experience keeps the world running. Share your COBOL knowledge and explore bank benefits designed around you.</p><div class="hero-note">${icon('sparkle')} For the people behind the programs.</div></div><div class="visual" aria-hidden="true"><div class="orbit"></div><div class="code-note"><div class="code-top"><span></span><span></span><span></span><b>EXPERIENCE.CBL</b></div><pre><strong>IDENTIFICATION DIVISION.</strong>\nPROGRAM-ID. YOUR-EXPERTISE.\n\n<strong>PROCEDURE DIVISION.</strong>\n  DISPLAY "EXPERIENCE MATTERS".\n  STOP RUN.</pre></div><div class="member-card"><div class="card-brand">${mark}HyperSquare</div><div class="card-chip"></div><div class="card-bottom"><div><small>THE EXPERT PROGRAM</small><b>KNOWLEDGE HAS VALUE</b></div>${icon('sparkle')}</div></div><div class="visual-badge">${icon('check')}<div><strong>Years of know-how.</strong>A new kind of opportunity.</div></div></div></div><div class="banks-heading" id="offers"><span class="eyebrow">EXPLORE THE BANK OFFER CONCEPTS</span><span class="sample-pill">Sample offers</span></div><div class="banks">${plans.map(p=>`<button class="bank-tile" type="button" data-bank="${p.id}" aria-label="Preview ${p.name} sample offer">${logo[p.id]}<span class="tile-sample">Sample</span><span class="corner-arrow">${icon('up')}</span></button>`).join('')}</div><p class="bank-disclaimer">Illustrative bank selections only. Bank names and marks belong to their respective owners; no sponsorship, partnership, or live offer is implied.</p></div></section>
<section class="qualify wrap" id="qualifications"><div class="section-intro"><div><div class="eyebrow">YOUR KNOWLEDGE. YOUR OPPORTUNITY.</div><h2>Who is qualified<br>for <em>this offer?</em></h2></div><p>You’ve spent years solving the problems that matter. We’re looking for experienced COBOL professionals who are ready to share how they think, build, and troubleshoot.</p></div><div class="qualifications"><article class="qualification"><div class="qual-top"><div class="qual-icon">${icon('code')}</div><span class="qual-number">01 / EXPERTISE</span></div><h3>You know COBOL.</h3><p>You have professional experience writing, maintaining, or debugging COBOL applications. Current and retired experts are welcome.</p></article><article class="qualification"><div class="qual-top"><div class="qual-icon">${icon('chat')}</div><span class="qual-number">02 / CONVERSATION</span></div><h3>You share your perspective.</h3><p>Join a guided interview about your experience, your approach to solving problems, and the lessons you’ve learned along the way.</p></article><article class="qualification"><div class="qual-top"><div class="qual-icon">${icon('screen')}</div><span class="qual-number">03 / WALKTHROUGH</span></div><h3>You show how it’s done.</h3><p>Complete a screen-recorded coding walkthrough using an approved sample task. Talk us through your decisions as you work.</p></article></div><p class="participation-note">${icon('shield')} You choose what to share. Use approved sample code, and keep employer and customer information private.</p></section>
<section class="steps-section wrap" id="how-it-works"><div class="flow-head"><div class="eyebrow">HOW CONTRIBUTIONS BECOME PERKS</div><h2>From your answer <em>to your benefit.</em></h2><p>Every step is visible, and you approve your own answers before anyone else sees them.</p></div><ol class="flow"><li><span class="flow-num">1</span><h3>Contribute</h3><p>Answer 3–5 specific questions in a session of about 15 minutes.</p></li><li><span class="flow-num">2</span><h3>Quality review</h3><p>You confirm or correct the AI’s summary. Then a second expert checks it. AI never approves its own drafts.</p></li><li><span class="flow-num">3</span><h3>Points</h3><p>Each confirmed answer earns points. <b>Example:</b> 50 points per answer.</p></li><li><span class="flow-num">4</span><h3>Perks</h3><p>Points unlock partner offers. <b>Example:</b> 500 points unlocks the sample offers above.</p></li></ol><p class="flow-note">${icon('info')} Amounts and offers are samples for this concept. A live program would confirm terms before you take part.</p></section>
<section class="offer-cta wrap"><div><h2>Your next opportunity starts here.</h2><p>Bring your experience. We’ll help you take the next step.</p></div><div class="cta-action"><a class="primary-button" href="#/register">Receive offer now! ${icon('arrow')}</a><span class="button-note">Explore the registration preview</span></div></section>
<section class="faq wrap"><div><div class="eyebrow">A LITTLE MORE CLARITY</div><h2>Before you get started.</h2></div><div><details><summary>Do I need to be currently employed?</summary><p>No. This concept welcomes experienced COBOL professionals, including retired engineers and independent consultants. Relevant professional experience is what matters.</p></details><details><summary>What will the interview and recording involve?</summary><p>The proposed program combines a guided conversation with a screen-recorded coding task. You would receive the task and recording details before participating and use approved sample code. No recording takes place on this prototype.</p></details><details><summary>Are these bank offers available now?</summary><p>This is a clickable concept. All amounts, rates, and benefits are fictional examples, and no bank partnership is confirmed. A live program would provide confirmed offer terms and eligibility before you participate.</p></details></div></section>${footer()}`;}
function planOption(p){return `<label class="plan ${state.plan===p.id?'selected':''}" data-plan-card="${p.id}"><input type="radio" name="plan" value="${p.id}" ${state.plan===p.id?'checked':''}><div class="plan-top"><span class="radio-dot" aria-hidden="true"></span><span class="plan-bank">${p.name}</span><span class="plan-tag">Sample · ${p.type}</span></div><div class="plan-body"><div><div class="plan-value">${p.value} <small>${p.short}</small></div><p class="plan-desc">${p.detail}</p></div><div class="plan-logo" aria-hidden="true">${logo[p.id]}</div></div></label>`;}
function registration(){if(plans.findIndex(p=>p.id===state.plan)>2)state.showAll=true;return `<div class="register-body"><aside class="register-aside"><a class="back-link" href="#/offers">${icon('back')} Back to offers</a><h1>A little about you. <em>A lot to offer.</em></h1><p>Join a community of experienced COBOL professionals helping the next generation build on what you know.</p><ol class="aside-steps"><li><span class="num">1</span><div><strong>Your details</strong><small>Let us know how to reach you.</small></div></li><li><span class="num">2</span><div><strong>Your preferred offer</strong><small>Choose the benefit that fits.</small></div></li><li><span class="num">3</span><div><strong>Your next chapter</strong><small>Continue to your Hypersquare space.</small></div></li></ol><div class="aside-bottom">${icon('shield')}<span>Your experience is yours to share.<br>You stay in control of what you contribute.</span></div></aside><section class="register-main animate-in"><div class="breadcrumb">Expert program ${icon('chevron')} <b>Registration</b></div><h2 class="registration-title">Let’s get you registered.</h2><p class="registration-sub">A few details, then an offer that feels right for you.</p><div class="demo-note">${icon('info')} Prototype only. Details stay in this page; no email is sent.</div><form id="registration-form" novalidate><div class="field-row"><div class="field"><label for="first">First name</label><input id="first" name="first" autocomplete="given-name" placeholder="e.g. Maria" value="${escapeHtml(state.first)}" required maxlength="80" aria-describedby="first-error"><div class="field-error" id="first-error"></div></div><div class="field"><label for="last">Last name</label><input id="last" name="last" autocomplete="family-name" placeholder="e.g. Johnson" value="${escapeHtml(state.last)}" required maxlength="80" aria-describedby="last-error"><div class="field-error" id="last-error"></div></div></div><div class="field"><label for="email">Email address</label><input id="email" name="email" type="email" autocomplete="email" placeholder="you@example.com" value="${escapeHtml(state.email)}" required maxlength="254" aria-describedby="email-error"><div class="field-error" id="email-error"></div></div><fieldset class="plan-fieldset" aria-describedby="plan-error"><legend>Choose your plan</legend><p class="plan-caption">Select one sample offer to preview your registration.</p><div class="plan-list">${plans.slice(0,3).map(planOption).join('')}<div id="additional-plans" class="plan-list ${state.showAll?'':'hide'}">${plans.slice(3).map(planOption).join('')}</div></div><button class="more-plans" type="button" id="more-plans" aria-expanded="${state.showAll}" aria-controls="additional-plans">${state.showAll?'Show fewer plans':'Show all 6 sample plans'} ${icon('down')}</button><div class="field-error" id="plan-error" role="status"></div></fieldset><label class="consent"><input type="checkbox" id="consent" name="consent" ${state.consent?'checked':''} aria-describedby="consent-error"><span>I have professional COBOL experience and am comfortable taking part in an interview and a screen-recorded coding walkthrough.</span></label><div class="field-error" id="consent-error" role="status"></div><button type="submit" class="primary-button submit-button">Submit and go ${icon('arrow')}</button><p class="confirmation-copy">When the program is live, you’ll receive an email confirmation with your selected offer and the next steps.</p></form></section></div>${footer()}`;}
function success(){const p=plans.find(p=>p.id===state.plan);if(!state.submitted||!p)return registration();return `<section class="success-wrap"><div class="success-card animate-in"><div class="success-symbol">${icon('check')}</div><div class="eyebrow">REGISTRATION PREVIEW COMPLETE</div><h1>You’re all set, ${escapeHtml(state.first)}.</h1><p>Your experience opens new doors.<br>Here’s what your next step would look like.</p><div class="summary-box">${logo[p.id]}<div><strong>${p.value} · ${p.short}</strong><p>${p.name} · Sample plan selected</p></div></div><div class="email-preview">${icon('mail')}<div><strong>Email confirmation preview</strong><p>A live confirmation would be sent to<br><b>${escapeHtml(state.email)}</b></p><p>No email was sent. This prototype does not submit or store your registration.</p></div></div><div class="handoff"><div class="eyebrow">YOUR NEXT DESTINATION</div><h2>Your Hypersquare space</h2><p>Your expert community is ready. Explore the leaderboard, take the weekly quiz, or try a sample coding walkthrough.</p><a class="primary-button" href="#/hypersquare">Open Hypersquare ${icon('arrow')}</a></div><div class="success-links"><a href="#/register">Edit your registration</a><a href="#/">Back to offers</a></div></div></section>${footer()}`;}
function route(){const hash=location.hash;const isDashboard=['','#/','#/hypersquare'].includes(hash);document.body.classList.toggle('dashboard-page',isDashboard);app.innerHTML=isDashboard?dashboardView():hash.startsWith('#/register')?registration():hash.startsWith('#/confirmation')?success():landing();bind();if(isDashboard)bindDashboard();if(!['#offers','#qualifications','#how-it-works'].includes(hash))window.scrollTo(0,0);else document.querySelector(hash)?.scrollIntoView();document.title=isDashboard?'Hypersquare — The expert community':hash.startsWith('#/register')?'Register — Hypersquare':'Hypersquare — Your experience opens doors';}
function showDialog(html){document.querySelector('#dialog-content').innerHTML=html;dialog.showModal();}
function openBank(id){const p=plans.find(x=>x.id===id);showDialog(`<div class="modal-logo">${logo[id]}</div><div class="eyebrow">SAMPLE OFFER · CONCEPT ONLY</div><h2 id="dialog-title">${p.value} ${p.short.toLowerCase()}</h2><p>${p.description}</p><p>Participation in the proposed expert program includes a guided interview and an approved, screen-recorded coding walkthrough.</p><button type="button" class="primary-button" id="choose-offer">Choose this sample plan ${icon('arrow')}</button><small>Illustrative terms only. No bank sponsorship or affiliation. Participation does not entitle you to a financial benefit in this prototype.</small>`);document.querySelector('#choose-offer').onclick=()=>{state.plan=id;dialog.close();location.hash='/register';};}
function openInfo(kind){showDialog(kind==='privacy'?`<div class="eyebrow">PROTOTYPE DETAILS</div><h2 id="dialog-title">Your information stays here.</h2><p>This demo keeps your inputs only in the current page’s memory. It does not submit registration details, send emails, record your screen, or save your information to a database. Refreshing the page clears your inputs.</p><p>A live program would explain recording permissions, how collected interviews and coding sessions are used, access, retention, and withdrawal before collecting data.</p>`:`<div class="eyebrow">PROGRAM CONCEPT</div><h2 id="dialog-title">Experience worth sharing.</h2><p>Hypersquare is a concept for inviting senior COBOL experts to share their knowledge through an interview and a screen-recorded coding walkthrough in exchange for confirmed banking benefits.</p><p>All offers shown here are fictional samples. Bank participation, rates, rewards, eligibility, and fulfillment terms must be confirmed before the program launches. No bank affiliation is implied.</p>`);}
function bind(){document.querySelectorAll('[data-bank]').forEach(el=>el.onclick=()=>openBank(el.dataset.bank));document.querySelectorAll('[data-info]').forEach(el=>el.onclick=()=>openInfo(el.dataset.info));const form=document.querySelector('#registration-form');if(!form)return;['first','last','email'].forEach(key=>form.elements[key].addEventListener('input',e=>{state[key]=e.target.value;clearFieldError(key);}));form.querySelectorAll('input[name="plan"]').forEach(el=>el.onchange=()=>{state.plan=el.value;form.querySelectorAll('.plan').forEach(card=>card.classList.toggle('selected',card.dataset.planCard===state.plan));document.querySelector('#plan-error').textContent='';});form.elements.consent.onchange=e=>{state.consent=e.target.checked;document.querySelector('#consent-error').textContent='';};document.querySelector('#more-plans').onclick=e=>{state.showAll=!state.showAll;document.querySelector('#additional-plans').classList.toggle('hide',!state.showAll);e.currentTarget.setAttribute('aria-expanded',String(state.showAll));e.currentTarget.innerHTML=(state.showAll?'Show fewer plans':'Show all 6 sample plans')+' '+icon('down');};form.onsubmit=submit;}
function clearFieldError(key){const input=document.getElementById(key);input.classList.remove('invalid');input.removeAttribute('aria-invalid');document.getElementById(key+'-error').textContent='';}
function submit(event){event.preventDefault();const form=event.currentTarget;let firstInvalid=null;['first','last','email'].forEach(key=>{const input=form.elements[key];state[key]=input.value.trim();input.value=state[key];clearFieldError(key);let msg='';if(!state[key])msg=key==='email'?'Enter your email address.':`Enter your ${key} name.`;else if(key==='email'&&!input.validity.valid)msg='Enter a valid email address.';if(msg){input.classList.add('invalid');input.setAttribute('aria-invalid','true');document.getElementById(key+'-error').textContent=msg;firstInvalid??=input;}});if(!state.plan){document.querySelector('#plan-error').textContent='Choose a sample plan to continue.';firstInvalid??=form.querySelector('input[name="plan"]');}if(!state.consent){document.querySelector('#consent-error').textContent='Confirm your experience and willingness to participate.';firstInvalid??=form.elements.consent;}if(firstInvalid){firstInvalid.focus();return;}state.submitted=true;location.hash='/hypersquare';}
document.querySelector('.modal-close').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const rect=dialog.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)dialog.close();}});
document.querySelectorAll('[data-scroll]').forEach(a=>a.onclick=e=>{e.preventDefault();const id=a.dataset.scroll;if(!document.getElementById(id)){location.hash='/offers';setTimeout(()=>document.getElementById(id)?.scrollIntoView({behavior:'smooth'}),50);}else document.getElementById(id).scrollIntoView({behavior:'smooth'});});
dialog.addEventListener('close',()=>dialog.classList.remove('dashboard-modal'));
window.addEventListener('hashchange',route);route();
